from browser_helpers import *
from cdp_input import Input

def ui_paused():
    if not data()['paused']:click('Pause simulation')
def rect(selector):return data('document.querySelector('+json.dumps(selector)+').getBoundingClientRect().toJSON()')
def drag(x,y,dx,dy):
    ab('mouse','move',round(x),round(y));ab('mouse','down');ab('mouse','move',round(x+dx*.4),round(y+dy*.4));ab('mouse','move',round(x+dx),round(y+dy));ab('mouse','up')
def ownfixture(name,obj):
    p=ROOT/name;p.write_text(json.dumps(obj,indent=2));return p
def upload(path):
    ab('upload','#import-file',path);ab('wait','--fn','window.orbitLab.getState().paused === true')
def root_reset():
    ab('select','#scenario','circular');ui_paused();ab('click','#tab-telemetry')

ab('open','http://127.0.0.1:8843/index.html');ab('set','viewport',1280,800);ab('wait','#play-btn');ui_paused();input_device=Input();ab('network','har','start');screenshot('08-offline-desktop.png')
check('HTTP app loads with dead external proxy',ab('get','url')=='http://127.0.0.1:8843/index.html')
# The external probe is deliberately separate from application traffic.
probe=ab('eval','fetch("https://example.com",{mode:"no-cors"}).then(()=>"unexpected success").catch(()=>"external request blocked")');check('external internet blocked',json.loads(probe)=='external request blocked');ab('console','--clear');ab('errors','--clear');ab('network','requests','--clear')
click('Simulation settings');check('default settings satisfy native numeric rules',data('document.getElementById("settings-form").checkValidity()'))
fill('Maximum integration step · t','.06');fill('Prediction horizon · t','600');fill('Prediction samples','650');fill('Trail duration · t','400');fill('Body display scale','1.25');click('Apply settings');cfg=data()['config'];check('settings submit changes live solver and display',cfg['dt']==.06 and cfg['horizon']==600 and cfg['resolution']==650 and cfg['bodyScale']==1.25)
click('Simulation settings');fill('Gravitational constant · G','0');click('Apply settings');check('invalid G is rejected without corrupting state',data()['config']['G']==1 and data('document.getElementById("settings-dialog").open'));fill('Gravitational constant · G','1.2');fill('Collision behavior','halt') if False else None;click('Apply settings');check('G can be configured',data()['config']['G']==1.2)
# Pointer input edits actual spacecraft vectors.
state=data();body=next(b for b in state['bodies'] if b['id']=='odyssey');pos=data('window.orbitLab.screenPosition("odyssey")');r=rect('#space');drag(r['left']+pos['x'],r['top']+pos['y'],23,-15);edited=next(b for b in data()['bodies'] if b['id']=='odyssey');check('paused pointer drag changes position',math.hypot(edited['x']-body['x'],edited['y']-body['y'])>10);check('position drag preserves velocity',edited['vx']==body['vx'] and edited['vy']==body['vy']);h=data('window.orbitLab.velocityHandle()');pre=data();drag(r['left']+h['x'],r['top']+h['y'],15,-7);post=data();v0=next(b for b in pre['bodies'] if b['id']=='odyssey');v1=next(b for b in post['bodies'] if b['id']=='odyssey');check('velocity handle changes real velocity continuously',0<math.hypot(v1['vx']-v0['vx'],v1['vy']-v0['vy'])<1);screenshot('09-pointer-state-edits.png')
pre=data()['camera'];drag(r['left']+90,r['top']+100,30,15);post=data()['camera'];check('canvas panning changes camera',abs(post['x']-pre['x'])>1);pre=data()['camera']['scale'];ab('mouse','move',round(r['left']+r['width']/2),round(r['top']+r['height']/2));input_device.wheel(r['left']+r['width']/2,r['top']+r['height']/2,-120);ab('wait','--fn',f'window.orbitLab.getState().camera.scale>{pre}');check('wheel zoom changes spatial scale',data()['camera']['scale']>pre);click('Fit entire system');check('fit accommodates star-to-spacecraft scale',data()['camera']['scale']<.5);screenshot('10-system-fit.png');click('Focus selected body');check('focus restores local usable scale',data()['camera']['scale']>.5)
# Timeline pointer and keyboard maneuver creation, component controls, and focus continuity.
r=rect('#timeline-track');ab('mouse','move',round(r['left']+r['width']*.28),round(r['top']+11));ab('mouse','down');ab('mouse','up');ab('wait','--fn','window.orbitLab.getState().nodes.length === 1');check('timeline pointer creates a future maneuver',data()['nodes'][0]['time']>data()['time']);ab('select','#node-mode','cartesian');fill('Inertial X Δv · u/t','.08');fill('Inertial Y Δv · u/t','-.03');ab('wait','--fn','window.orbitLab.getPrediction().planned.events.some(e=>e.a===.08)');check('Cartesian maneuver previews with actual magnitude',abs(float(ab('get','text','#node-magnitude').split()[0])-math.hypot(.08,.03))<.0001);ab('focus','#node-a');ab('press','Control+a');ab('keyboard','inserttext','.1234');time.sleep(.3);check('focused numeric input survives live telemetry refresh',ab('get','value','#node-a')=='.1234' or ab('get','value','#node-a')=='0.1234');fill('Burn time · mission t','-1');check('past-time error is visible',bool(ab('get','text','#node-error')));fill('Burn time · mission t',str(data()['time']+20));click('Apply maneuver');click('Remove');ab('focus','#timeline-track');ab('press','Enter');check('timeline keyboard creates a maneuver',len(data()['nodes'])==1);click('Remove')
# Every preset is exercised through selection and genuine forward play.
for preset in ['circular','elliptical','hohmann','moon','slingshot','threebody','escape']:
    ab('select','#scenario',preset);ui_paused();before=data();initial=next(b for b in before['bodies'] if b['id']=='odyssey');click('Play simulation');ab('wait','--fn',f"window.orbitLab.getState().time > {before['time']+3}");ui_paused();after=data();moved=next(b for b in after['bodies'] if b['id']=='odyssey');check(preset+' preset has integrated motion',math.hypot(moved['x']-initial['x'],moved['y']-initial['y'])>.1);check(preset+' telemetry remains finite',all(math.isfinite(v) for b in after['bodies'] for v in [b['x'],b['y'],b['vx'],b['vy']]));
    if preset=='hohmann':check('Hohmann preset schedules two burns',len(after['nodes'])==2)
    if preset=='escape':check('escape telemetry reports unbound apoapsis',ab('get','text','#tel-apo').startswith('∞'))
root_reset()
# Display overlays draw and controls remain responsive.
for name,id in [('Sphere of influence','soi'),('Gravity field','potential'),('Acceleration vectors','acceleration'),('Integration error','error')]:ab('check','#layer-'+id)
screenshot('11-gravity-and-vector-overlays.png');check('gravity legend visible',ab('is','visible','#potential-key')=='true')
for id in ['soi','potential','acceleration','error']:ab('uncheck','#layer-'+id)
for id in ['trajectories','trails','velocity','guides','encounters']:ab('uncheck','#layer-'+id);ab('check','#layer-'+id)
# Exact state vector, mass, radius, display, primary, second craft, persistence.
click('Edit selected body');fill('Mass · m','.000002');fill('Physical radius · u','.3');fill('Display size · px','9');ab('select','#body-primary','');click('Apply body changes');check('body physical properties and free-flight primary apply',next(b for b in data()['bodies'] if b['id']=='odyssey')['mass']==.000002 and 'primaryId' not in next(b for b in data()['bodies'] if b['id']=='odyssey'))
click('Plan a maneuver');click('Save checkpoint');cp=data();click('Single step');click('Return to checkpoint');check('free-flight maneuver checkpoint restores',data()['time']==cp['time'] and len(data()['nodes'])==1);click('Save mission');click('Single step');click('Simulation settings');click('Load saved mission');check('free-flight maneuver save loads successfully',len(data()['nodes'])==1 and data()['time']==cp['time'])
export=ROOT/'mission-export.json';ab('download','#export-btn',export);saved=json.loads(export.read_text());check('JSON export contains actual scheduled state',saved['format']=='orbitlab-mission' and len(saved['nodes'])==1)
# Reload resets the internal counter; imported node IDs must still remain unique.
ab('reload');ui_paused();upload(export);ab('wait','--fn','window.orbitLab.getState().nodes.length===1');click('Plan a maneuver');ids=[n['id'] for n in data()['nodes']];check('imported mission can add unique maneuver IDs',len(ids)==len(set(ids))==2)
old=data();bad=ownfixture('invalid-mission.json',{'format':'orbitlab-mission','version':1,'bodies':[]});ab('upload','#import-file',bad);ab('wait','--text','Import rejected');check('malformed import is atomic',data()['bodies']==old['bodies'] and data()['nodes']==old['nodes']);screenshot('12-import-error-state.png')
# High zoom, capped velocity handle: a tiny displacement must not jump speed.
root_reset();ab('select','#reference-frame','primary');r=rect('#space');pos=data('window.orbitLab.screenPosition("odyssey")');
for i in range(3):
    scale=data()['camera']['scale'];input_device.wheel(r['left']+pos['x'],r['top']+pos['y'],-180);ab('wait','--fn',f'window.orbitLab.getState().camera.scale>{scale}')
before=data();craft=next(b for b in before['bodies'] if b['id']=='odyssey');primary=next(b for b in before['bodies'] if b['id']=='terra');check('high-zoom case really caps the velocity handle',math.hypot(craft['vx']-primary['vx'],craft['vy']-primary['vy'])*before['camera']['scale']*before['config']['vectorScale']>140);h=data('window.orbitLab.velocityHandle()');drag(r['left']+h['x'],r['top']+h['y'],4,0);after=data();b0=next(b for b in before['bodies'] if b['id']=='odyssey');b1=next(b for b in after['bodies'] if b['id']=='odyssey');change=math.hypot(b1['vx']-b0['vx'],b1['vy']-b0['vy']);check('capped velocity handle has no initial discontinuity',change<.1,change)
# Narrow layout: actual controls, scrolling, editing, state retention and screenshots.
ab('set','viewport',390,844);ab('scroll','up',2000);screenshot('13-mobile-390x844.png');check('mobile has no horizontal overflow',data('document.documentElement.scrollWidth<=innerWidth'))
ab('click','#mobile-systems');ab('select','#scenario','elliptical');ui_paused();check('mobile scenario control is connected',data()['scenario']=='elliptical');ab('click','#mobile-telemetry');ab('scroll','down',500);screenshot('14-mobile-telemetry.png');check('mobile telemetry populated',ab('get','text','#selected-name')=='Odyssey');click('Plan a maneuver');fill('Prograde Δv · u/t','.09');fill('Radial Δv · u/t','.01');ab('wait','--fn','window.orbitLab.getPrediction().planned.events.some(e=>e.a===.09)');screenshot('15-mobile-maneuver.png');check('mobile maneuver editing connected',data()['nodes'][0]['a']==.09);click('Remove');ab('click','#mobile-systems');click('Simulation settings');fill('Prediction horizon · t','450');click('Apply settings');check('mobile settings submit works',data()['config']['horizon']==450);ab('click','#mobile-telemetry');ab('scroll','up',2000);click('Single step');check('mobile transport single-step works',data()['paused']);click('Open field guide');screenshot('16-mobile-field-guide.png');click('Ready for flight')
# Return to desktop to inspect navigation and request/console health.
ab('set','viewport',1280,800);ab('scroll','up',2000);click('Mission log '+ab('get','text','#log-count'));check('mission-log navigation works',ab('is','visible','#mission-log')=='true');screenshot('17-mission-log.png');click('← Return to simulation');check('return navigation restores sandbox',ab('is','visible','#workspace')=='true');check('no uncaught errors in extended flows',ab('errors')=='');check('no console errors after separate proxy probe',ab('console')=='');req=ab('network','requests');check('application makes no external network requests','https://' not in req);ab('network','har','stop',ROOT/'logs/offline-workflows.har');screenshot('18-final-desktop.png');input_device.close();print('Extended workflows completed',flush=True)
